def big_sum(arr):
    if not arr:
        raise ValueError("Array must not be empty")
    return max(arr) + min(arr)

# Example usage and test
assert big_sum([1, 2, 3]) == 4
assert big_sum([-10, 0, 10, 20]) == 10
assert big_sum([5]) == 10
